//		Exec(ctx)
func (_c *DisputeCreateBulk) OnConflictColumns(columns ...string) *DisputeUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &DisputeUpsertBulk{
		create: _c,
	}
}

